`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes izhikevich.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg signed [31:0] i_in;
    wire signed [31:0] v0, v1, v2, v3, u0, u1, u2, u3;  wire s0, s1, s2, s3;
    izh_neuron #(.A(5),  .B(51), .C(-65*256), .D(8*256)) rs (clk, rst, en, i_in, v0, u0, s0);
    izh_neuron #(.A(5),  .B(51), .C(-55*256), .D(4*256)) ib (clk, rst, en, i_in, v1, u1, s1);
    izh_neuron #(.A(5),  .B(51), .C(-50*256), .D(2*256)) ch (clk, rst, en, i_in, v2, u2, s2);
    izh_neuron #(.A(26), .B(51), .C(-65*256), .D(2*256)) fs (clk, rst, en, i_in, v3, u3, s3);
    integer n0 = 0, n1 = 0, n2 = 0, n3 = 0;
    initial begin
        f = $fopen("izhikevich.csv", "w"); $fdisplay(f, "t_ms,i,v_rs,u_rs,v_ib,v_ch,v_fs");
        i_in = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 600; t = t + 1) begin                 // 0.5 ms per step -> 300 ms
            i_in = (t < 50) ? 0 : 10*256;
            @(posedge clk); #1;
            n0 = n0 + s0; n1 = n1 + s1; n2 = n2 + s2; n3 = n3 + s3;
            $fdisplay(f, "%0.1f,%0d,%0d,%0d,%0d,%0d,%0d", t*0.5, i_in, s0 ? 30*256 : v0, u0, s1 ? 30*256 : v1, s2 ? 30*256 : v2, s3 ? 30*256 : v3);
        end
        check("spikes_RS", n0, 7);
        check("spikes_IB", n1, 10);
        check("spikes_CH", n2, 25);
        check("spikes_FS", n3, 32);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
